input.command:
repo=${MEASUREMENT_ENV:-$HOME/measurement_env}
echo "===== VTI rig card (Identity section) ====="
sed -n '1,60p' "$repo/hera/rig-cards/VTI.md"

sess="$HOME/VTI_local_data/zack/20260822-vti-02"
uv run --no-project python - "$sess/20260822_measure.ipynb" <<'PY'
import json,sys
nb=json.load(open(sys.argv[1],encoding="utf-8"))
def grab(sub):
    for c in nb["cells"]:
        s="".join(c.get("source",[]))
        if sub in s: return c,s
    return None,None
print("── GATE VALIDATORS (SAFETIES limits) ──")
for ln in grab("TG_MIN")[1].splitlines():
    if any(k in ln for k in ("MIN","CAP")): print("  "+ln.strip())
print("\n── GEOMETRY ──")
for ln in grab("t_tg =")[1].splitlines():
    if ln.startswith("t_"): print("  "+ln.strip())
print("\n── MEAS-CONFIG / CONTACT-MAP ──")
_,s=grab('"source": "T_0"')
for ln in s.splitlines():
    if any(k in ln for k in ('sr0','sr1','sr2','sr3','source','drain','bias_channel')) and '#' in ln or '"source": "T_0", "drain"' in ln:
        pass
_,mc=grab('meas_config = {')
for ln in mc.splitlines():
    if any(k in ln for k in ('"source"','"sr0"','"sr1"','"sr2"','"sr3"','bias_channel','sr0_gain')): print("  meas: "+ln.strip())
_,w=grab("WIRING = {")
for ln in w.splitlines():
    if any(k in ln for k in ('source','sr1+','sr2+','sr3+')): print("  wire: "+ln.strip())
print("\n── INSTRUMENT ADDRESSES (fixed) ──")
for c in nb["cells"]:
    s="".join(c.get("source",[]))
    for ln in s.splitlines():
        if any(k in ln for k in ("SR830('sr0'","SR830('sr1'","SR830('sr2'","SR830('sr3'","k_2400_tg'","k_2400_bg'","dc205 =","FastBi1K5")): print("  "+ln.strip())
PY
